"""spike15a statistics + table.md (v8 rules). usage: stats15.py [smoke|testc]. Paired percentile bootstrap over episodes, 20000 resamples, one shared resample index for every contrast."""
import sys, os, json, numpy as np
ROOT = os.path.abspath(os.path.join(os.path.dirname(os.path.abspath(__file__)), '..')); MODE = sys.argv[1] if len(sys.argv) > 1 else 'testc'
STORE = os.path.join(ROOT, '.scratch/s15/smoke_episodes.json' if MODE == 'smoke' else 'results/spike15a/testc_episodes.json'); OUTD = os.path.join(ROOT, '.scratch/s15' if MODE == 'smoke' else 'results/spike15a')
E = json.load(open(STORE)); g = lambda k: np.array(E[k]['success'], float); n = len(g('R0')); B = 20000
IDX = np.random.default_rng(15).integers(0, n, (B, n))
def bs(x): return x[IDX].mean(1)
def ci(x, lev=95): b = bs(x); a = (100 - lev) / 2; return 100 * x.mean(), 100 * np.percentile(b, a), 100 * np.percentile(b, 100 - a)
def fmt(t): return f'{t[0]:+.1f} [{t[1]:+.1f}, {t[2]:+.1f}]'
def fmtp(x, lev=95): m, lo, hi = ci(x, lev); return f'{m:.1f} [{lo:.1f}, {hi:.1f}]'
M = {'R0 T-adapt3-full': g('R0'), 'R1 true theta': g('R1'), 'R2 + true chain state': g('R2'), 'R4 T-oracle': g('R4')}
if 'R5' in E: M['R5 canonical T-oracle'] = g('R5')
if 'Rrev1' in E: M['Rrev1 fitted theta + true chain state (reverse order)'] = g('Rrev1')
M['L-est-full (mean of 3)'] = np.mean([g(f'lest#{s}') for s in range(3)], 0)
for s in range(3): M[f'L-est-full #{s}'] = g(f'lest#{s}')
M['L-dec4 (3 seeds merged)'] = np.mean([g(f'dec4_s{s}') for s in range(3)], 0)
for s in range(3): M[f'L-dec4 seed {s}'] = g(f'dec4_s{s}')
M['L-ens (dec4 theta mean)'] = g('ens_dec4'); M['C-MAP (MAP + multi-start)'] = g('C_map1_ms')
R0, R1, R2, R4 = M['R0 T-adapt3-full'], M['R1 true theta'], M['R2 + true chain state'], M['R4 T-oracle']; D4 = M['L-dec4 (3 seeds merged)']
def p_le(x, thr): return max((bs(x) * 100 <= thr).mean(), 1 / (B + 1))          # one-sided bootstrap p: P*(diff <= thr)
def p_ge(x, thr): return max((bs(x) * 100 >= thr).mean(), 1 / (B + 1))
d13, d13b, d14 = R1 - R0, R4 - R2, D4 - R0
c13 = ci(d13); c13b = ci(d13b); c14 = ci(d14, 90)
v13 = (c13[0] >= 10) and (c13[1] > 0); v13b = c13b[2] < 5; v14 = (c14[1] > -10) and (c14[2] < 10)
p = {'H13': p_le(d13, 0.0), 'H13b': p_ge(d13b, 5.0), 'H14': max(p_le(d14, -10.0), p_ge(d14, 10.0))}
order = sorted(p, key=p.get); adj = {}; run = 0.0
for i, k in enumerate(order): run = max(run, min(1.0, (3 - i) * p[k])); adj[k] = run
L = [f'# spike15a TEST-C table ({"SMOKE on CAL 1000-1009, not evidence" if MODE == "smoke" else "locked set seeds 30000-30499"}; n={n}; generated by spike15a/stats15.py)', '']
L += ['## Verdicts (rules of hypothesis card v8, applied verbatim)', '', '| hypothesis | statistic | CI | rule | verdict (unadjusted) | one-sided bootstrap p | Holm-adjusted p |', '|---|---|---|---|---|---|---|',
      f'| H13 estimation dominates headroom | R1-R0 = {c13[0]:+.1f} pp | 95% [{c13[1]:+.1f}, {c13[2]:+.1f}] | point >= +10 and lower > 0 | **{"SUPPORTED" if v13 else "NOT supported"}** | {p["H13"]:.5f} (H0: diff<=0) | {adj["H13"]:.5f} |',
      f'| H13b probe cost small | R4-R2 = {c13b[0]:+.1f} pp | 95% [{c13b[1]:+.1f}, {c13b[2]:+.1f}] | upper < +5 | **{"SUPPORTED" if v13b else "NOT supported"}** | {p["H13b"]:.5f} (H0: diff>=5) | {adj["H13b"]:.5f} |',
      f'| H14 estimator duel equivalent | L-dec4 - R0 = {c14[0]:+.1f} pp | 90% [{c14[1]:+.1f}, {c14[2]:+.1f}] | inside +-10 (TOST) | **{"SUPPORTED" if v14 else "NOT supported"}** | {p["H14"]:.5f} (TOST max of two) | {adj["H14"]:.5f} |', '']
L += ['Holm: step-down on the three one-sided bootstrap p-values (family of 3). Per hypothesis card v8.1: family-wise alpha = 0.05 on the Holm-adjusted one-sided bootstrap p-values.', '']
for k, v in (('H13', v13), ('H13b', v13b), ('H14', v14)): L.append(f'* {k}: unadjusted {"supported" if v else "not supported"}; Holm-adjusted p = {adj[k]:.5f} -> survives Holm (alpha 0.05): {"yes" if (v and adj[k] < 0.05) else "no"}.')
L += ['', '## Success rate per method (95% bootstrap CI, %)', '', '| method | success % [95% CI] |', '|---|---|'] + [f'| {k} | {fmtp(v)} |' for k, v in M.items()]
L += ['', '## Paired differences (pp [95% CI])', '', '| contrast | diff |', '|---|---|']
con = [('R1 - R0 (parameter error)', R1 - R0), ('R2 - R1 (chain state)', R2 - R1), ('R4 - R2 (probe cost, incl. R3 omitted)', R4 - R2), ('R4 - R0 (total headroom)', R4 - R0)]
if 'R5 canonical T-oracle' in M: con += [('R5 - R4 (planner search)', M['R5 canonical T-oracle'] - R4), ('R5 - R0', M['R5 canonical T-oracle'] - R0)]
con += [(f'{k} - R0', M[k] - R0) for k in ('L-est-full (mean of 3)', 'L-dec4 (3 seeds merged)', 'L-ens (dec4 theta mean)', 'C-MAP (MAP + multi-start)')] + [(f'L-dec4 seed {s} - R0', M[f'L-dec4 seed {s}'] - R0) for s in range(3)]
con += [('L-dec4 - L-est-full', D4 - M['L-est-full (mean of 3)']), ('L-dec4 - C-MAP', D4 - M['C-MAP (MAP + multi-start)']), ('L-ens - C-MAP', M['L-ens (dec4 theta mean)'] - M['C-MAP (MAP + multi-start)'])]
L += [f'| {a} | {fmt(ci(x))} |' for a, x in con]
rv = 'Rrev1 fitted theta + true chain state (reverse order)'
if rv in M: L += ['', '## Reverse-order ladder (descriptive only; forward order: R0 -> R1 -> R2)', '', '| step | diff |', '|---|---|', f'| Rrev1 - R0 (chain state first) | {fmt(ci(M[rv] - R0))} |', f'| R2 - Rrev1 (then parameters) | {fmt(ci(R2 - M[rv]))} |', f'| forward: R1 - R0 (parameters first) | {fmt(ci(R1 - R0))} |', f'| forward: R2 - R1 (then chain state) | {fmt(ci(R2 - R1))} |']
L += ['', '## Recovered fraction (X - R0) / (R1 - R0), same resample in numerator and denominator; percentile 95% CI', '', '| method | fraction [95% CI] | denominator (R1-R0, pp) |', '|---|---|---|']
den = IDX_den = bs(R1 - R0)
for k in ('L-est-full (mean of 3)', 'L-dec4 (3 seeds merged)', 'L-ens (dec4 theta mean)', 'C-MAP (MAP + multi-start)', 'R2 + true chain state', 'R4 T-oracle'):
    nb = bs(M[k] - R0); ok = np.abs(den) > 1e-9; r = nb[ok] / den[ok]; pt = (M[k] - R0).mean() / (R1 - R0).mean()
    L.append(f'| {k} | {pt:.2f} [{np.percentile(r, 2.5):.2f}, {np.percentile(r, 97.5):.2f}] | {100*(R1-R0).mean():+.1f} |')
L += ['', '## Instability (episodes with a numerical blow-up in the true plant, %)', ''] + [f'* {k}: {100*np.mean(np.array(E[k]["inst"])>0):.1f}' for k in E]
open(os.path.join(OUTD, 'table.md'), 'w').write('\n'.join(L) + '\n'); print('\n'.join(L))
